                            availability_report: Power_Propulsion_Availability_Supervisor.AvailabilityReport => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val availability_decisionValue: Power_Propulsion_Availability_Supervisor.AvailabilityDecision = get_availability_decision().get
    if(!availability_decision(availability_decisionValue)) {
      testFailures = testFailures :+ st"'availability_decision' did not match expected: value of the outgoing data port is ${availability_decisionValue}"
