    val availability_reportValue: Power_Propulsion_Availability_Supervisor.AvailabilityReport = get_availability_report().get
    if(!availability_report(availability_reportValue)) {
      testFailures = testFailures :+ st"'availability_report' did not match expected: value of the outgoing data port is ${availability_reportValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


